const item = $input.first().json;
const sourceItem = $items("Build Script Prompt")[0]?.json || {};
const id = item.id || sourceItem.id || sourceItem.parsed_idea?.id || "idea_001";

const scriptMarkdown =
  item.output?.[0]?.content?.[0]?.text ||
  item.output?.content?.[0]?.text ||
  item.text ||
  '';

return [
  {
    json: {
      id,
      script_markdown: scriptMarkdown,
      generated_at: new Date().toISOString(),
      source: 'openai',
    },
  },
];

const item = $input.first().json;

const scriptMarkdown = item.script_markdown || "";

function extractDurationSeconds(markdown) {
  const match =
    markdown.match(/Длительность:\s*(\d+)\s*сек/i) ||
    markdown.match(/(\d+)\s*секунд/i);

  if (!match) return 18;

  const value = Number(match[1]);
  return Number.isFinite(value) && value > 0 ? value : 18;
}

const durationSeconds = extractDurationSeconds(scriptMarkdown);

const videoPayload = {
  id: item.id || "idea_001",
  format: "vertical_video",
  aspect_ratio: "9:16",
  platform: "reels_tiktok_shorts",
  language: "ru",
  duration_seconds: durationSeconds,
  source: item.source || "openai",
  generated_at: item.generated_at,
  script_markdown: scriptMarkdown,
  production_status: "script_ready",
  next_step: "video_generation",
  video_requirements: {
    resolution: "1080x1920",
    captions: true,
    voiceover: true,
    background_music: true,
    safe_zones: true
  }
};

return [
  {
    json: {
      id: item.id || "idea_001",
      video_payload: videoPayload
    }
  }
];

const item = $input.first().json;

return [
  {
    json: {
      id: item.id,
      status: 'ready_for_video_generation',
      video_payload: item.video_payload,
      completed_at: new Date().toISOString()
    }
  }
];

const item = $input.first().json;

const videoPayload = item.video_payload || {};
const scriptMarkdown =
  videoPayload.script_markdown ||
  item.script_markdown ||
  "";

if (!scriptMarkdown) {
  throw new Error("script_markdown not found");
}

function cleanText(value) {
  return String(value || "")
    .replace(/\\n/g, "\n")
    .replace(/\r/g, "")
    .trim();
}

const markdown = cleanText(scriptMarkdown);

function extractSection(markdown, heading) {
  const escapedHeading = heading.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const regex = new RegExp(
    `##\\s*${escapedHeading}\\s*\\n([\\s\\S]*?)(?=\\n##\\s+|\\n#\\s+|$)`,
    "i"
  );

  const match = markdown.match(regex);
  return match ? match[1].trim() : "";
}

function firstNonEmptyLine(text) {
  return cleanText(text)
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .find(Boolean) || "";
}

function stripMarkdownListMarker(line) {
  return String(line || "")
    .replace(/^\s*[-*]\s+/, "")
    .replace(/^\s*\d+[.)]\s+/, "")
    .trim();
}

function parseListSection(sectionText) {
  return cleanText(sectionText)
    .split("\n")
    .map(stripMarkdownListMarker)
    .map((line) => line.replace(/^["“”]+|["“”]+$/g, "").trim())
    .filter(Boolean)
    .filter((line) => !line.startsWith("|"))
    .filter((line) => !/^[-:| ]+$/.test(line));
}

function parseVideoStructureTable(markdown) {
  const section =
    extractSection(markdown, "4. Video structure") ||
    extractSection(markdown, "Video structure") ||
    extractSection(markdown, "4. Структура ролика") ||
    extractSection(markdown, "Структура ролика");

  if (!section) return [];

  const lines = section
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);

  const tableLines = lines.filter((line) => line.startsWith("|") && line.endsWith("|"));

  if (tableLines.length < 3) return [];

  const dataLines = tableLines.filter((line) => {
    const normalized = line.replace(/\s/g, "");
    return !normalized.includes("|---") && !normalized.includes("|:---");
  });

  const header = dataLines.shift();
  if (!header) return [];

  return dataLines.map((line, index) => {
    const cells = line
      .split("|")
      .slice(1, -1)
      .map((cell) => cell.trim());

    const [block, time, content, visual, onScreenText] = cells;

    return {
      scene: index + 1,
      block: block || `Scene ${index + 1}`,
      duration: time || "",
      content: content || "",
      visual: visual || "",
      on_screen_text: onScreenText || ""
    };
  }).filter((scene) => scene.content || scene.visual);
}

function extractTitle(markdown) {
  const sectionTitle =
    firstNonEmptyLine(extractSection(markdown, "1. Video title")) ||
    firstNonEmptyLine(extractSection(markdown, "Video title")) ||
    "";

  if (sectionTitle) return sectionTitle.replace(/^#+\s*/, "").trim();

  const h1 = markdown.match(/^#\s+(.+)$/m);
  if (h1) {
    return h1[1]
      .replace(/^idea_\d+\.\s*/i, "")
      .replace(/Vertical Video Script/i, "")
      .trim();
  }

  return "Untitled Short";
}

function extractVoiceover(markdown) {
  const section =
    extractSection(markdown, "5. Voiceover") ||
    extractSection(markdown, "Voiceover") ||
    "";

  const lines = parseListSection(section);

  if (lines.length > 0) {
    return lines.join("\n");
  }

  return cleanText(section);
}

function extractCaptions(markdown) {
  const section =
    extractSection(markdown, "6. On-screen text") ||
    extractSection(markdown, "On-screen text") ||
    "";

  return parseListSection(section);
}

function extractCTA(markdown) {
  const section =
    extractSection(markdown, "8. CTA") ||
    extractSection(markdown, "CTA") ||
    "";

  return firstNonEmptyLine(section);
}

const title = extractTitle(markdown);
const voiceover = extractVoiceover(markdown);
const captions = extractCaptions(markdown);
const scenes = parseVideoStructureTable(markdown);
const cta = extractCTA(markdown);

if (!Array.isArray(scenes) || scenes.length === 0) {
  throw new Error("Could not extract scenes from Markdown video structure table");
}

const videoPipelineJson = {
  id: item.id || videoPayload.id || "idea_001",
  title,
  duration_seconds: Number(videoPayload.duration_seconds || item.duration_seconds || 18),
  language: "en",
  aspect_ratio: videoPayload.aspect_ratio || item.aspect_ratio || "9:16",
  resolution: videoPayload.video_requirements?.resolution || "1080x1920",
  voiceover,
  captions,
  scenes,
  cta,
  source_script_format: "markdown"
};

return [
  {
    json: {
      id: item.id || videoPayload.id || "idea_001",
      status: "ready_for_video_pipeline",
      video_pipeline_json: videoPipelineJson,
      source_video_payload: videoPayload,
      completed_at: new Date().toISOString()
    }
  }
];

const item = $input.first().json;

const packages = item.scene_packages || [];

if (!Array.isArray(packages) || packages.length === 0) {
  throw new Error("scene_packages is empty or not an array");
}

return packages.map((scenePackage) => ({
  json: {
    id: item.id,
    title: item.title,
    language: item.language,
    duration_seconds: item.duration_seconds,
    aspect_ratio: item.aspect_ratio,
    ...scenePackage
  }
}));

const items = $input.all();

if (!items.length) {
  throw new Error("No scene packages found");
}

return items.map((inputItem) => {
  const item = inputItem.json;

  if (!item.keyframe_prompt) {
    throw new Error(`keyframe_prompt not found for ${item.scene_id || "unknown scene"}`);
  }

  return {
    json: {
      id: item.id,
      title: item.title,
      language: item.language || "en",
      duration_seconds: item.duration_seconds,
      aspect_ratio: item.aspect_ratio,

      scene_id: item.scene_id,
      scene_number: item.scene_number,
      block: item.block,
      duration: item.duration,
      content: item.content,
      visual: item.visual,
      on_screen_text: item.on_screen_text,

      source: "keyframe-generation-layer",
      provider: "higgsfield",
      model: "soul",
      soul_endpoint: "/v1/text2image/soul",

      dop_prompt: item.dop_prompt,
      motions: item.motions,

      soul_payload: {
        params: {
          seed: null,
          prompt: item.keyframe_prompt,
          quality: item.quality || "720p",
          batch_size: item.batch_size || 1,
          enhance_prompt: item.enhance_prompt ?? true,
          style_strength: item.style_strength ?? 1,
          width_and_height: item.width_and_height || "1152x2048"
        },
        webhook: null
      }
    }
  };
});

const item = $input.first().json;

if (item.status !== "completed") {
  return [
    {
      json: {
        status: "not_ready",
        provider_status: item.status,
        request_id: item.request_id,
        status_url: item.status_url,
        source: "higgsfield-soul"
      }
    }
  ];
}

const keyframeUrl = item.images?.[0]?.url;

if (!keyframeUrl) {
  throw new Error("Soul completed, but images[0].url was not found");
}

return [
  {
    json: {
      scene_id: "scene_01",
      keyframe_status: "ready",
      keyframe_request_id: item.request_id,
      keyframe_url: keyframeUrl,
      source: "higgsfield-soul",
      completed_at: new Date().toISOString()
    }
  }
];

const items = $input.all();

const PUBLIC_FILES_BASE_URL = "https://skirt-expired-mutual-scope.trycloudflare.com";

if (!items.length) {
  throw new Error("No storyboard frame items found");
}

return items.map((inputItem) => {
  const item = inputItem.json;

  if (item.status !== "storyboard_frame_ready") {
    throw new Error(`Storyboard frame is not ready for ${item.scene_id || "unknown scene"}`);
  }

  if (!item.local_frame_file_path) {
    throw new Error(`local_frame_file_path not found for ${item.scene_id || "unknown scene"}`);
  }

  const relativePath = item.local_frame_file_path.replace(/^data\//, "");
  const publicImageUrl = `${PUBLIC_FILES_BASE_URL.replace(/\/$/, "")}/${relativePath}`;

  const prompt =
    item.dop_prompt ||
    [
      "Animate this clean storyboard frame as a short vertical 9:16 kids animated scene.",
      "Keep the same characters, same world, same central object, same colors and same lighting from the frame.",
      "Use simple readable motion. One clear action only.",
      "Do not add text, captions, logos, signs, UI, numbers, letters or watermarks."
    ].join(" ");

  return {
    json: {
      id: item.id || "idea_001",
      title: item.title || "",
      language: item.language || "en",
      duration_seconds: item.duration_seconds || 18,
      aspect_ratio: item.aspect_ratio || "9:16",

      scene_id: item.scene_id,
      scene_number: item.scene_number,
      block: item.block || "",
      duration: item.duration || "",
      content: item.content || "",
      visual: item.visual || "",
      on_screen_text: item.on_screen_text || "",

      source: "higgsfield-dop-turbo",
      provider: "higgsfield",
      model: "dop-turbo",
      dop_endpoint: "/higgsfield-ai/dop/turbo",

      frame_file_path: item.frame_file_path,
      local_frame_file_path: item.local_frame_file_path,
      public_image_url: publicImageUrl,

      dop_prompt: prompt,

      dop_payload: {
        seed: null,
        prompt,
        motions: null,
        image_url: publicImageUrl,
        enhance_prompt: true
      },

      source_storyboard_frame: item,
      completed_at: new Date().toISOString()
    }
  };
});

const statusItems = $input.all();
const sourceItems = $items("Build DoP Payload");

if (!statusItems.length) {
  throw new Error("No DoP status items found");
}

if (!sourceItems.length) {
  throw new Error("No source DoP payload items found");
}

if (statusItems.length !== sourceItems.length) {
  throw new Error(`Items count mismatch: statusItems=${statusItems.length}, sourceItems=${sourceItems.length}`);
}

return statusItems.map((statusItem, index) => {
  const status = statusItem.json;
  const source = sourceItems[index].json;

  if (status.status !== "completed") {
    throw new Error(`DoP render is not completed for item ${index + 1}. Status: ${status.status}`);
  }

  const videoUrl = status.video?.url;

  if (!videoUrl) {
    throw new Error(`Completed DoP render has no video.url for item ${index + 1}`);
  }

  return {
    json: {
      id: source.id || "idea_001",
      status: "scene_video_ready",
      source: "normalize-scene-video-result",

      title: source.title || "",
      language: source.language || "en",
      duration_seconds: source.duration_seconds || 18,
      aspect_ratio: source.aspect_ratio || "9:16",

      scene_id: source.scene_id,
      scene_number: source.scene_number,
      block: source.block || "",
      duration: source.duration || "",
      content: source.content || "",
      visual: source.visual || "",
      on_screen_text: source.on_screen_text || "",

      provider: "higgsfield",
      model: "dop-turbo",

      request_id: status.request_id,
      status_url: status.status_url,
      cancel_url: status.cancel_url,

      frame_file_path: source.frame_file_path,
      local_frame_file_path: source.local_frame_file_path,
      public_image_url: source.public_image_url,

      dop_prompt: source.dop_prompt,
      video_url: videoUrl,

      source_dop_status: status,
      source_dop_payload: source,

      completed_at: new Date().toISOString()
    }
  };
});

const input = $input.first()?.json || {};
const now = new Date();

const runMode = input.run_mode || "manual_test";
const triggerSource = input.trigger_source || "manual";
const runId =
  input.run_id ||
  `${runMode}_${now.toISOString().replace(/[:.]/g, "-")}`;

return [
  {
    json: {
      ...input,

      id: input.id || "idea_001",
      run_mode: runMode,
      trigger_source: triggerSource,
      run_id: runId,

      raw_idea:
        input.raw_idea ||
        "A short animated kids video: a small cute helper enters a colorful toy-like world, finds a magical object, makes a funny mistake, chooses the correct object, and triggers a bright transformation. The format should feel trend-native for YouTube Shorts / Reels.",

      target_audience: input.target_audience || "children and family audience",
      platform: input.platform || "YouTube Shorts / Reels",
      duration_seconds: Number(input.duration_seconds || 18),

      trend_direction:
        input.trend_direction ||
        "current kids short-form content: fast 3D/cartoon stories, visual guessing games, object transformations, funny safe mistakes, bright characters, repeatable episode structure, strong retention in the first seconds",

      research_goal:
        input.research_goal ||
        "identify trend-native mechanics for kids short-form content and convert them into a trend-replication brief optimized for recognizability, retention and repeatability",

      safety_constraints:
        input.safety_constraints ||
        "no violence, no fear, no dangerous challenges, no adult themes, no toxic behavior, no manipulative calls to action, safe for children and family viewing",

      brand_constraints:
        input.brand_constraints ||
        "Analyze popular kids short-form mechanics freely, including game-like, toy-like, animated, cinematic, challenge-based, transformation-based and character-driven formats. Replicate the strongest trend mechanics, pacing, visual grammar, character archetypes, scene rhythm and payoff structure as closely as possible.",

      output_goal:
        input.output_goal ||
        "produce a trend-informed English-language kids short-form brief that can be used for script, storyboard, keyframe prompts, video generation and voiceover",

      input_context_ready_at: now.toISOString()
    }
  }
];

const item = $input.first().json;

const rawText =
  item.output?.[0]?.content?.[0]?.text ||
  item.output?.content?.[0]?.text ||
  item.content?.[0]?.text ||
  item.text ||
  "";

if (!rawText || typeof rawText !== "string") {
  throw new Error("Parsed idea text not found in LLM output");
}

function extractJson(text) {
  const cleaned = text
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```$/i, "")
    .trim();

  try {
    return JSON.parse(cleaned);
  } catch (directError) {
    const firstBrace = cleaned.indexOf("{");
    const lastBrace = cleaned.lastIndexOf("}");

    if (firstBrace === -1 || lastBrace === -1 || lastBrace <= firstBrace) {
      throw new Error("No JSON object found in parsed idea text");
    }

    const jsonCandidate = cleaned.slice(firstBrace, lastBrace + 1);
    return JSON.parse(jsonCandidate);
  }
}

const parsed = extractJson(rawText);

const requiredFields = [
  "id",
  "topic",
  "content_category",
  "audience",
  "platform",
  "duration_seconds",
  "tone",
  "goal",
  "retention_strategy",
  "story_premise",
  "main_character",
  "world",
  "central_object",
  "plot",
  "visual_direction",
  "scene_generation_rules"
];

for (const field of requiredFields) {
  if (parsed[field] === undefined || parsed[field] === null) {
    throw new Error(`Parsed idea missing required field: ${field}`);
  }
}

return [
  {
    json: {
      id: parsed.id || "idea_001",
      status: "parsed_idea_ready",
      source: "normalize-parsed-idea",

      topic: parsed.topic || "",
      content_category: parsed.content_category || "",
      audience: parsed.audience || "дети и семейная аудитория",
      platform: parsed.platform || "YouTube Shorts / Reels",
      duration_seconds: Number(parsed.duration_seconds || 18),
      tone: parsed.tone || "",
      goal: parsed.goal || "",

      retention_strategy: parsed.retention_strategy || {},
      story_premise: parsed.story_premise || "",
      main_character: parsed.main_character || {},
      supporting_character: parsed.supporting_character || {},
      world: parsed.world || {},
      central_object: parsed.central_object || {},
      plot: parsed.plot || {},

      visual_direction: parsed.visual_direction || "",
      scene_generation_rules: parsed.scene_generation_rules || {},

      safety_rules: Array.isArray(parsed.safety_rules) ? parsed.safety_rules : [],
      brand_ip_exclusions: Array.isArray(parsed.brand_ip_exclusions)
        ? parsed.brand_ip_exclusions
        : [],
      negative_references: Array.isArray(parsed.negative_references)
        ? parsed.negative_references
        : [],

      brief_source: parsed.brief_source || "trend_brief",
      raw_parsed_idea_json: parsed,
      completed_at: new Date().toISOString()
    }
  }
];

const item = $input.first().json;

// DEBUG MODE: 6 queries to avoid burning YouTube API quota during workflow testing.
// Later we can return to 12–15 queries for production mode.
const queries = [
  "kids animation shorts",
  "kids 3D cartoon shorts",
  "kids game animation shorts",
  "kids transformation animation shorts",
  "kids guessing game shorts",
  "family friendly 3D shorts"
];

return queries.map((query, index) => ({
  json: {
    id: item.id || "idea_001",
    source: "youtube",
    query_id: `youtube_query_${String(index + 1).padStart(2, "0")}`,
    query,

    raw_idea: item.raw_idea || "",
    target_audience: item.target_audience || "children and family audience",
    platform: item.platform || "YouTube Shorts / Reels",
    duration_seconds: Number(item.duration_seconds || 18),

    trend_direction: item.trend_direction || "",
    research_goal: item.research_goal || "",
    safety_constraints: item.safety_constraints || "",
    brand_constraints: item.brand_constraints || "",
    output_goal: item.output_goal || ""
  }
}));

const items = $input.all();

const out = [];

for (const item of items) {
  const source = item.json;
  const results = source.items || [];

  for (const result of results) {
    const videoId = result.id?.videoId;
    if (!videoId) continue;

    out.push({
      json: {
        source: "youtube",
        query_id: source.query_id || "",
        query: source.query || "",
        video_id: videoId,
        title: result.snippet?.title || "",
        description: result.snippet?.description || "",
        channel_id: result.snippet?.channelId || "",
        channel_title: result.snippet?.channelTitle || "",
        published_at: result.snippet?.publishedAt || "",
        thumbnail_url:
          result.snippet?.thumbnails?.high?.url ||
          result.snippet?.thumbnails?.medium?.url ||
          result.snippet?.thumbnails?.default?.url ||
          ""
      }
    });
  }
}

const unique = new Map();

for (const item of out) {
  if (!unique.has(item.json.video_id)) {
    unique.set(item.json.video_id, item);
  }
}

return Array.from(unique.values());

const items = $input.all();

const videoIds = items
  .map((item) => item.json.video_id)
  .filter(Boolean);

const uniqueIds = [...new Set(videoIds)];

const chunks = [];
const chunkSize = 50;

for (let i = 0; i < uniqueIds.length; i += chunkSize) {
  chunks.push(uniqueIds.slice(i, i + chunkSize));
}

return chunks.map((chunk, index) => ({
  json: {
    source: "youtube",
    batch_id: `youtube_stats_batch_${String(index + 1).padStart(2, "0")}`,
    video_ids: chunk,
    video_ids_csv: chunk.join(","),
    video_count: chunk.length
  }
}));

const items = $input.all();
const out = [];

function parseIsoDurationToSeconds(duration) {
  if (!duration || typeof duration !== "string") return null;

  const match = duration.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  if (!match) return null;

  const hours = Number(match[1] || 0);
  const minutes = Number(match[2] || 0);
  const seconds = Number(match[3] || 0);

  return hours * 3600 + minutes * 60 + seconds;
}

for (const item of items) {
  const videos = item.json.items || [];

  for (const video of videos) {
    const stats = video.statistics || {};
    const snippet = video.snippet || {};
    const contentDetails = video.contentDetails || {};
    const thumbnails = snippet.thumbnails || {};

    const durationSeconds = parseIsoDurationToSeconds(contentDetails.duration);

    out.push({
      json: {
        source: "youtube",
        video_id: video.id,
        title: snippet.title || "",
        description: snippet.description || "",
        channel_id: snippet.channelId || "",
        channel_title: snippet.channelTitle || "",
        published_at: snippet.publishedAt || "",
        default_language: snippet.defaultLanguage || "",
        default_audio_language: snippet.defaultAudioLanguage || "",
        tags: snippet.tags || [],
        category_id: snippet.categoryId || "",
        duration_iso: contentDetails.duration || "",
        duration_seconds: durationSeconds,
        licensed_content: contentDetails.licensedContent ?? null,
        definition: contentDetails.definition || "",
        caption: contentDetails.caption || "",
        view_count: Number(stats.viewCount || 0),
        like_count: Number(stats.likeCount || 0),
        comment_count: Number(stats.commentCount || 0),
        thumbnail_url:
          thumbnails.maxres?.url ||
          thumbnails.standard?.url ||
          thumbnails.high?.url ||
          thumbnails.medium?.url ||
          thumbnails.default?.url ||
          ""
      }
    });
  }
}

return out;

const items = $input.all();

const now = new Date();

function daysSince(dateString) {
  const date = new Date(dateString);
  if (Number.isNaN(date.getTime())) return null;

  const diffMs = now.getTime() - date.getTime();
  return Math.max(1, Math.floor(diffMs / (1000 * 60 * 60 * 24)));
}

function includesAny(text, words) {
  const lower = String(text || "").toLowerCase();
  return words.some((word) => lower.includes(word.toLowerCase()));
}

function countMatches(text, words) {
  const lower = String(text || "").toLowerCase();
  return words.reduce((count, word) => {
    return lower.includes(word.toLowerCase()) ? count + 1 : count;
  }, 0);
}

const positiveKidsSignals = [
  "kids",
  "children",
  "baby",
  "toddler",
  "preschool",
  "nursery",
  "rhymes",
  "cartoon",
  "animation",
  "animated",
  "3d",
  "shorts",
  "learn",
  "learning",
  "fun",
  "family",
  "friendly",
  "toy",
  "colors",
  "numbers",
  "animals",
  "song",
  "story",
  "adventure",
  "good habits",
  "sharing",
  "caring",
