function parseDurationTextToSeconds(value) {
  const text = String(value || "").trim();

  if (!text) return null;

  const rangeMatch = text.match(/(\d+):([0-5]?\d)\s*[-–—]\s*(\d+):([0-5]?\d)/);
  if (rangeMatch) {
    const start = Number(rangeMatch[1]) * 60 + Number(rangeMatch[2]);
    const end = Number(rangeMatch[3]) * 60 + Number(rangeMatch[4]);
    const duration = end - start;
    return duration > 0 ? duration : null;
  }

  const secondsMatch = text.match(/(\d+(?:\.\d+)?)\s*(?:s|sec|second|seconds)/i);
  if (secondsMatch) {
    const seconds = Number(secondsMatch[1]);
    return Number.isFinite(seconds) && seconds > 0 ? seconds : null;
  }

  return null;
}

function getDurationWithFfprobe(videoFilePath) {
  try {
    let ffprobePath = "ffprobe";

    try {
      const ffprobe = require("ffprobe-static");
      if (ffprobe?.path && fs.existsSync(ffprobe.path)) {
        ffprobePath = ffprobe.path;
      }
    } catch (error) {
      // Use system ffprobe fallback.
    }

    const durationRaw = execFileSync(
      ffprobePath,
      [
        "-v",
        "error",
        "-show_entries",
        "format=duration",
        "-of",
        "default=noprint_wrappers=1:nokey=1",
        videoFilePath
      ],
      {
        encoding: "utf8"
      }
    ).trim();

    const seconds = Number(durationRaw);

    if (Number.isFinite(seconds) && seconds > 0) {
      return {
        seconds,
        source: "ffprobe"
      };
    }

    return null;
  } catch (error) {
    return {
      seconds: null,
      source: "fallback",
      error: error.message
    };
  }
}

